def copiar_vinculos(apps, schema_editor):
    Apresentacao = apps.get_model("shopify", "ApresentacaoServicoShopify")
    for apresentacao in Apresentacao.objects.exclude(servico_alternativo_id=None):
        apresentacao.servicos_vinculados.add(apresentacao.servico_alternativo_id)


def restaurar_vinculo_unico(apps, schema_editor):
    Apresentacao = apps.get_model("shopify", "ApresentacaoServicoShopify")
    for apresentacao in Apresentacao.objects.prefetch_related("servicos_vinculados"):
        primeiro = apresentacao.servicos_vinculados.order_by("nome", "pk").first()
        if primeiro:
            Apresentacao.objects.filter(pk=apresentacao.pk).update(
                servico_alternativo_id=primeiro.pk)


